import { and, asc, eq, gt, isNull, like } from "drizzle-orm";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { archivePatch, shouldFilterArchived } from "@/lib/soft-delete";
import { getDb, members, organizations } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId, toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { ArchiveScope, OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

/** Organization ids read per page when a job walks the whole table. */
const ORG_PAGE_SIZE = 100;

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

/**
 * One page of organization ids in id order, strictly after `afterId`. Deleted
 * (archived) organizations are left out unless `scope.includeArchived` is set.
 */
export async function listOrgIdPage(
  afterId: OrgId | null,
  limit: number,
  scope: ArchiveScope = {},
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(
      and(
        afterId === null ? undefined : gt(organizations.id, afterId),
        shouldFilterArchived(scope)
          ? isNull(organizations.archivedAt)
          : undefined,
      ),
    )
    .orderBy(asc(organizations.id))
    .limit(limit)
    .all();

  return rows.map((row) => brandId<OrgId>(row.id));
}

/**
 * Yields every matching organization id, one keyset page at a time, so a job
 * covers the whole table however many organizations there are. The next page
 * is read only after the current one has been handled.
 */
export async function* eachOrgId(
  scope: ArchiveScope = {},
  pageSize: number = ORG_PAGE_SIZE,
): AsyncGenerator<OrgId> {
  let afterId: OrgId | null = null;

  for (;;) {
    const page = await listOrgIdPage(afterId, pageSize, scope);
    for (const orgId of page) yield orgId;

    if (page.length < pageSize) return;
    afterId = page[page.length - 1] ?? null;
  }
}

