import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
const NOW = new Date("2026-06-01T07:00:00.000Z");
const PAST = "2026-01-01T00:00:00.000Z";

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});
afterAll(() => cleanup());

describe("scratch verification", () => {
  it("overdue covers orgs without usage rows, skips deleted, pages through all", async () => {
    resetOverdueTracking();
    const tenants = [];
    for (let i = 0; i < 5; i += 1) tenants.push(await createTenant(`ov-${i}`));
    // none have a usage row (no recompute)
    const gone = tenants[2]!;
    await orgRepo.archiveOrg(gone.org.id);
    for (const t of tenants) {
      const n = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
      await issueRepo.insertIssue(issueInput(t.org.id, t.project.id, { dueAt: PAST }), t.userIds.owner, n);
    }

    const ids: string[] = [];
    for await (const id of orgRepo.eachOrgId({}, 2)) ids.push(id);
    const live = tenants.filter((t) => t.org.id !== gone.org.id).map((t) => t.org.id);
    expect(ids.sort()).toEqual([...live].sort().concat([]).length ? expect.arrayContaining(live) as never : []);
    expect(ids).not.toContain(gone.org.id);

    const seen: string[] = [];
    const off = subscribe("issue.overdue", (p) => void seen.push(p.orgId));
    await runOverdueIssueJob(NOW);
    off();
    expect(seen.sort()).toEqual([...live].sort());
  });

  it("rollup queue: never-recounted first, deltas do not reorder, recount moves to back", async () => {
    const made = [];
    for (let i = 0; i < 30; i += 1) made.push(await createTenant(`rq-${i}`));
    const first = await usageRepo.listOrgIdsForRollup(1);
    expect(first.length).toBe(1);
    await usageRepo.incrementUsage(first[0]!, { issuesUsed: 3 });
    expect(await usageRepo.listOrgIdsForRollup(1)).toEqual(first);

    await runUsageRollupJob(NOW);
    const recounted = await usageRepo.listOrgIdsForRollup(100);
    expect(recounted.length).toBe(100);
    // after one pass, the 25 recounted orgs are at the back of the queue
    const front = await usageRepo.listOrgIdsForRollup(5);
    for (const id of front) {
      const usage = await usageRepo.getUsage(id);
      expect(usage.measuredAt).toBeDefined();
    }
    await runUsageRollupJob(NOW);
    const all = await usageRepo.listOrgIdsForRollup(1000);
    const liveCount = (await Array.fromAsync(orgRepo.eachOrgId())).length;
    expect(all.length).toBe(liveCount);
    for (const t of made) expect(all).toContain(t.org.id);
  });
});

