import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import Database from "better-sqlite3";
import { describe, expect, it } from "vitest";
import { runMigrations } from "@/server/db/migrate";

describe("scratch migrate", () => {
  it("adds recounted_at to an older organization_usage table, idempotently", async () => {
    const dir = mkdtempSync(join(tmpdir(), "scratch-mig-"));
    const path = join(dir, "old.db");
    const old = new Database(path);
    old.exec(`CREATE TABLE organization_usage (
      org_id TEXT PRIMARY KEY NOT NULL, seats_used INTEGER NOT NULL DEFAULT 0,
      projects_used INTEGER NOT NULL DEFAULT 0, issues_used INTEGER NOT NULL DEFAULT 0,
      storage_mb_used INTEGER NOT NULL DEFAULT 0, measured_at TEXT NOT NULL)`);
    old.exec(`INSERT INTO organization_usage (org_id, measured_at) VALUES ('o1', '2026-01-01T00:00:00.000Z')`);
    old.close();

    await runMigrations(path);
    await runMigrations(path);

    const check = new Database(path);
    const cols = (check.prepare("PRAGMA table_info(organization_usage)").all() as { name: string }[]).map((c) => c.name);
    const row = check.prepare("SELECT org_id, recounted_at FROM organization_usage").get() as { org_id: string; recounted_at: string | null };
    check.close();
    rmSync(dir, { recursive: true, force: true });

    expect(cols.filter((c) => c === "recounted_at")).toHaveLength(1);
    expect(row).toEqual({ org_id: "o1", recounted_at: null });
  });
});

